 field.beams[0].start={50,1,0};auto miss=storm_ship_laser::splitSurface(surface,{Vec3{-1,0,0},0,true,{0,1,0},0,1,0,{field.beams[0]}},wood);assert(miss.detachedArea==0);assert(!storm_ship_laser::beamSeversSupport(original,original,field.beams,{0,1,0}));std::cout<<"mast partial notch / actual complete section / near miss / original support PASS"<<std::endl;
